    #[test]
    fn scoped_tokens_are_read_from_headers_without_using_urls() {
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-agent-hub-embed-token",
            HeaderValue::from_static("embed-secret"),
        );
        assert_eq!(
            embed_token_from_headers(&headers).as_deref(),
            Some("embed-secret")
        );

        headers.clear();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Webhook webhook-secret"),
        );
        assert_eq!(
            webhook_token_from_headers(&headers).as_deref(),
            Some("webhook-secret")
        );

        headers.clear();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer ahe_embed-secret"),
        );
        assert_eq!(
            client_access_token_from_headers(&headers).as_deref(),
            Some("ahe_embed-secret")
        );

        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer unrelated-secret"),
        );
        assert_eq!(client_access_token_from_headers(&headers), None);
    }

    #[test]
    fn agent_access_distinguishes_owner_admin_and_member() {
        let mut agent = test_agent();
        let owner = test_user(agent.owner_id, "member");
        let admin = test_user(Uuid::new_v4(), "admin");
        let super_admin = test_user(Uuid::new_v4(), "super_admin");
        let member = test_user(Uuid::new_v4(), "member");

        assert_eq!(
            agent_access(&agent, &owner),
            AgentAccess {
                can_manage: true,
                can_administer: true,
                can_invoke: true
            }
        );
        assert_eq!(
            agent_access(&agent, &admin),
            AgentAccess {
                can_manage: true,
                can_administer: true,
                can_invoke: false
            }
        );
        assert_eq!(
            agent_access(&agent, &super_admin),
            AgentAccess {
                can_manage: true,
                can_administer: true,
                can_invoke: false
            }
        );
        assert_eq!(
            agent_access(&agent, &member),
            AgentAccess {
                can_manage: false,
                can_administer: false,
                can_invoke: false
            }
        );

        agent.visibility = "public_to".into();
        agent.public_to = vec![member.id];
        assert!(agent_access(&agent, &member).can_invoke);
        assert!(!agent_access(&agent, &admin).can_invoke);

        agent.visibility = "public".into();
        assert!(agent_access(&agent, &member).can_invoke);
        assert!(agent_access(&agent, &admin).can_invoke);
    }

    #[test]
    fn run_event_sanitizers_remove_nul_bytes() {
        let mut text = "before\0after".to_owned();
        sanitize_run_event_text(&mut text);
        assert_eq!(text, "before\u{FFFD}after");

        let payload = json!({
            "output": "ELF\0bin\0",
            "nested": ["x\0", {"key": "v\0"}],
            "count": 3,
            "flag": true,
            "nothing": null,
        });
        let sanitized = sanitize_run_event_payload(payload);
        assert_eq!(sanitized["output"], json!("ELF\u{FFFD}bin\u{FFFD}"));
        assert_eq!(sanitized["nested"][0], json!("x\u{FFFD}"));
        assert_eq!(sanitized["nested"][1]["key"], json!("v\u{FFFD}"));
        assert_eq!(sanitized["count"], json!(3));
        assert_eq!(sanitized["flag"], json!(true));
        assert_eq!(sanitized["nothing"], json!(null));

        // Object keys must be sanitized too: jsonb rejects NUL anywhere.
        let mut keyed = serde_json::Map::new();
        keyed.insert("bad\0key".into(), json!("value"));
        keyed.insert("ok".into(), json!("value"));
        let sanitized_keyed = sanitize_run_event_payload(Value::Object(keyed));
        let object = sanitized_keyed.as_object().unwrap();
        assert!(object.contains_key("bad\u{FFFD}key"));
        assert!(!object.keys().any(|key| key.contains('\0')));
        assert_eq!(object["ok"], json!("value"));
    }

