    #[sqlx::test(migrations = "./migrations")]
    #[ignore = "requires DATABASE_URL and PostgreSQL CREATE DATABASE privilege"]
    async fn agent_deletion_requires_owner_or_super_administrator_and_is_idempotent(pool: PgPool) {
        let owner_id = Uuid::new_v4();
        let member_id = Uuid::new_v4();
        let admin_id = Uuid::new_v4();
        let owner_agent_id = Uuid::new_v4();
        let admin_agent_id = Uuid::new_v4();
        let owner_token = format!("ahs_{}", Uuid::new_v4().simple());
        let member_token = format!("ahs_{}", Uuid::new_v4().simple());
        let admin_token = format!("ahs_{}", Uuid::new_v4().simple());
        let unique = Uuid::new_v4().simple().to_string();
        for (id, token, label, role) in [
            (owner_id, &owner_token, "owner", "member"),
            (member_id, &member_token, "member", "member"),
            (admin_id, &admin_token, "admin", "admin"),
        ] {
            sqlx::query(
                "INSERT INTO users
                     (id, email, password, display_name, role)
                 VALUES ($1, $2, 'unused', $3, $4)",
            )
            .bind(id)
            .bind(format!("delete-auth-{label}-{unique}@example.com"))
            .bind(label)
            .bind(role)
            .execute(&pool)
            .await
            .unwrap();
            sqlx::query(
                "INSERT INTO sessions (token_hash, user_id, expires_at)
                 VALUES ($1, $2, now() + interval '1 hour')",
            )
            .bind(sha256_hex(token))
            .bind(id)
            .execute(&pool)
            .await
            .unwrap();
        }
        for agent_id in [owner_agent_id, admin_agent_id] {
            sqlx::query(
                "INSERT INTO agents (id, owner_id, name, instructions, visibility)
                 VALUES ($1, $2, 'Delete authorization Agent', 'test', 'private')",
            )
            .bind(agent_id)
            .bind(owner_id)
            .execute(&pool)
            .await
            .unwrap();
        }
        let state = Arc::new(test_state_with_browser_session_auth(pool.clone()));

        let forbidden = delete_agent(
            State(state.clone()),
            session_headers(&member_token),
            Path(owner_agent_id),
        )
        .await
        .unwrap_err();
        assert_eq!(forbidden.status, StatusCode::FORBIDDEN);
        assert!(sqlx::query_scalar::<_, Option<DateTime<Utc>>>(
            "SELECT deleted_at FROM agents WHERE id = $1"
        )
        .bind(owner_agent_id)
        .fetch_one(&pool)
        .await
        .unwrap()
        .is_none());

        assert_eq!(
            delete_agent(
                State(state.clone()),
                session_headers(&owner_token),
                Path(owner_agent_id),
            )
            .await
            .unwrap(),
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            delete_agent(
                State(state.clone()),
                session_headers(&owner_token),
                Path(owner_agent_id),
            )
            .await
            .unwrap(),
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            delete_agent(
                State(state),
                session_headers(&admin_token),
                Path(admin_agent_id),
            )
            .await
            .unwrap(),
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT count(*) FROM agents
                 WHERE id = ANY($1) AND deleted_at IS NOT NULL"
            )
            .bind(vec![owner_agent_id, admin_agent_id])
            .fetch_one(&pool)
            .await
            .unwrap(),
            2
        );
    }

